    assert is_strong_password("") is False


def test_missing_upper():
    """No uppercase -> False"""
    assert is_strong_password("abcdefg1!") is False


def test_missing_lower():
    """No lowercase -> False"""
    assert is_strong_password("ABCDEFG1!") is False


def test_missing_digit():
    """No digit -> False"""
    assert is_strong_password("Abcdefg!") is False


def test_missing_symbol():
    """No symbol (all alphanumeric) -> False"""
    assert is_strong_password("Abcdefg1") is False


def test_multiple_missing():
    """Missing multiple requirements -> False"""
    assert is_strong_password("abcdefg") is False


def test_non_string_int():
    """Non-string input (int) -> TypeError"""
    try:
        is_strong_password(12345)
        assert False, "Expected TypeError"
    except TypeError:
        pass


def test_non_string_list():
    """Non-string input (list) -> TypeError"""
    try:
        is_strong_password(["A", "b", "c"])
        assert False, "Expected TypeError"
    except TypeError:
        pass


def test_non_string_none():
    """Non-string input (None) -> TypeError"""
    try:
        is_strong_password(None)
        assert False, "Expected TypeError"
    except TypeError:
        pass


def test_non_string_bytes():
    """Non-string input (bytes) -> TypeError"""
    try:
        is_strong_password(b"Abc1!xyz")
        assert False, "Expected TypeError"
    except TypeError:
        pass


def test_space_is_symbol():
    """Space is non-alphanumeric so counts as symbol"""
    # A-b-c-d-e-f-g-1-space = 9
    assert is_strong_password("Abcdefg1 ") is True


def test_various_symbols():
    """Various non-alphanumeric characters count as symbols"""
    assert is_strong_password("Abcdefg1#") is True
    assert is_strong_password("Abcdefg1$") is True
    assert is_strong_password("Abcdefg1&") is True
    assert is_strong_password("Abcdefg1*") is True


def test_return_type_true():
    """Result should be exactly True (bool)"""
    result = is_strong_password("Abc1!xyz")
    assert result is True


def test_return_type_false():
    """Result should be exactly False (bool)"""
    result = is_strong_password("abcdef")
    assert result is False


def test_only_one_of_each():
    """Minimal valid: 8 chars with at least one of each type"""
    # a-A-1-!-b-c-d-e = 8
    assert is_strong_password("aA1!bcde") is True


def test_multiple_digits_and_symbols():
    """Multiple digits and symbols is fine"""
    assert is_strong_password("aA1!1!bc") is True


def test_unicode_upper_counts():
    """Unicode uppercase letter satisfies upper requirement"""
    # \u00C1-b-c-1-!-x-y-z = 8
    assert is_strong_password("\u00C1bc1!xyz") is True


def test_unicode_lower_counts():
    """Unicode lowercase letter satisfies lower requirement"""
    # A-\u00E1-b-c-1-!-x-y = 8
    assert is_strong_password("A\u00E1bc1!xy") is True


def test_no_repeat_limit():
    """No minimum unique character requirement per spec"""
    assert is_strong_password("Aa1!Aa1!") is True


def test_all_same_char_too_short():
    """All same char, too short -> False"""
    assert is_strong_password("Aaaaaa1") is False


def test_8_chars_boundary_true():
    """Exactly 8 chars with all requirements is True"""
    # A-a-1-!-x-y-z-z = 8
    assert is_strong_password("Aa1!xyzz") is True


def test_7_chars_boundary_false():
    """Exactly 7 chars with all requirements is False"""
    # A-a-1-!-x-y-z = 7
    assert is_strong_password("Aa1!xyz") is False
